import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Take the person's statement: record their due-total now (late charges included, at most the sheet's cap) and the sheet's today, bind
 *  each of their claims that counts to its due as shown now (late charge and floor included: while bound it no longer
 *  follows the sheet's today; one already bound is bound again to the figure it shows), and unbind the rest (their due is live again; a claim deferred on today is left unbound). A settled claim's
 *  fixed due is left as it is.
 *  <p>Taken as of a date (on or before the sheet's today; refused after it, or for a person added after it), the
 *  same is done with the sheet as it stood at the end of that date: every change made while the sheet's today was on
 *  or before it counts, every later one does not, and the date stands in for the sheet's today. Their claims that
 *  counted then are bound to their dues as shown then, the rest are unbound, and the date is recorded as the statement's. */
public class SaveStatement {
    public void save(@Val StatementRequest request, @Val Person loaded, PersonRepository people,
            ClaimRepository claims, RateRepository rates, SheetRepository sheets, SettingRepository settings,
            Out<Statement> statement, Out<PersonResponse> saved) throws InvalidPersonException {
        people.lock(loaded);
        Person person = people.find(loaded.sheetId(), loaded.id());
        String sheetId = person.sheetId();
        LocalDate today = sheets.today(sheetId);
        LocalDate asOf = request.asOf() != null ? LocalDate.parse(request.asOf()) : null;
        if (asOf != null && today != null && asOf.isAfter(today)) {
            throw new InvalidPersonException("A statement cannot be taken as of a date after the sheet's today ("
                    + today + ").");
        }
        if (asOf != null && !people.addedBy(person, asOf)) {
            throw new InvalidPersonException(person.name() + " was not on the sheet on " + asOf + ".");
        }
        LocalDate on = asOf != null ? asOf : today;
        List<Claim> theirs = claims.listForPerson(sheetId, person.id());
        Rounding now = Rounding.of(sheetId, settings, sheets, claims);

        List<Claim> then;
        Grades grades;
        Holds holds;
        LocalDate retiredFrom;
        Rates ratesThen;
        DatedAmount floor;
        LateCharge late;
        BigDecimal cap;
        if (asOf == null) {
            then = theirs;
            grades = person.grades();
            holds = person.holds();
            retiredFrom = person.retiredFrom();
            ratesThen = rates;
            floor = settings.floor(sheetId);
            late = LateCharge.of(sheetId, settings, sheets, claims, people);
            cap = settings.cap(sheetId);
        } else {
            then = claims.listForPersonAsOf(sheetId, person.id(), asOf);
            grades = people.gradesAsOf(person, asOf);
            holds = people.holdsAsOf(person, asOf);
            retiredFrom = people.retiredFromAsOf(person, asOf);
            ratesThen = rates.asOf(sheetId, asOf);
            SettingHistory history = settings.historyAsOf(sheetId, asOf);
            floor = history::floorOn;
            LocalDate policy = settings.policyDate(sheetId);
            late = new LateCharge(history::latePctOn, asOf, new Rounding(policy != null ? policy : asOf,
                    now.numbered(), history.of(SettingHistory.ROUNDING)), LateCharge.Grace.of(history, Map.of(person.id(), grades)));
            cap = history.capOn(asOf);
        }

        BigDecimal total = Dues.capped(Dues.total(sheetId, then, grades, holds, retiredFrom, on, ratesThen, floor,
                late), cap);
        Map<Long, BigDecimal> bound = new HashMap<>();
        for (Claim c : then) {
            if (Dues.counts(c, holds, retiredFrom, on)) {
                bound.put(c.id(), Dues.shown(c, grades, ratesThen, floor, late));
            }
        }
        for (Claim c : theirs) {
            if (bound.containsKey(c.id())) {
                claims.state(c, true, bound.get(c.id()));
            } else if (c.stated()) {
                claims.state(c, false, null);
            }
        }
        people.stated(person, total, on);
        statement.set(new Statement(sheetId, person.name(), total, bound.size(), asOf));
    }

    private static Claim asOpenUnstated(Claim c) {
        return new Claim(c.id(), c.sheetId(), c.personId(), c.amount(), c.date(), c.note(), ClaimStatus.OPEN,
                c.number(), null, c.openedBy(), false, null, c.corrects(), c.dueBy(), null, c.proofs(), c.splitFrom(), c.lateEntry(), c.reminded(), c.ref(), c.tags(), c.waived(), c.photos(), c.held());
    }

    /** The claim's due now, as its row shows it: the figure a statement bound it to, else live (amount times its
     *  person's grade rate in force on the claim's date, divided by 100, rounded to two decimals as the claim rounds), with
     *  the late charge on it as of the sheet's today added, at least the sheet's floor in force on its date; null
     *  when it has no figure. */
    /** Why the claim cannot be opened as it is: its note is empty and its due is above the sheet's note threshold
     *  in force on its date; null when it may be opened. */
    static String noteRequired(Claim claim, ClaimRepository claims, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets) {
        if (claim.note() != null && !claim.note().isBlank()) {
            return null;
        }
        BigDecimal threshold = settings.noteThreshold(claim.sheetId()).on(claim.date());
        if (threshold == null) {
            return null;
        }
        BigDecimal due = dueNow(claim, claims, people, rates, settings, sheets);
        if (due == null || due.compareTo(threshold) <= 0) {
            return null;
        }
        return "This claim's due " + due + " is above the note threshold " + threshold
                + "; give it a note before it is opened.";
    }

    /** Whether the claim, opened as it is, goes to REVIEW instead of OPEN: its due is above the sheet's review
     *  threshold in force on its date (no threshold, or a due of n/a, is within it). */
    static boolean reviewRequired(Claim claim, ClaimRepository claims, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets) {
        BigDecimal threshold = settings.reviewThreshold(claim.sheetId()).on(claim.date());
        if (threshold == null) {
            return false;
        }
        BigDecimal due = dueNow(claim, claims, people, rates, settings, sheets);
        return due != null && due.compareTo(threshold) > 0;
    }

    /** The claim as it stood at the end of the day (see ClaimRepository.listAsOf); null when it did not exist then. */
    private static Claim then(Claim claim, LocalDate end, ClaimRepository claims) {
        return claims.listAsOf(claim.sheetId(), end).stream().filter(c -> c.id() == claim.id()).findFirst()
                .orElse(null);
    }

    /** The claim's due as its row showed it at the end of the day, as the as-of view works it out: the sheet as it
     *  stood then (its person's grades, the rates, floor, late percents, grace and rounding), the date standing in
     *  for the sheet's today. */
    private static BigDecimal dueAsOf(Claim then, LocalDate end, ClaimRepository claims, PersonRepository people,
            RateRepository rates, SettingRepository settings, SheetRepository sheets) {
        var person = people.find(then.sheetId(), then.personId());
        var grades = people.gradesAsOf(person, end);
        var history = settings.historyAsOf(then.sheetId(), end);
        LocalDate policy = settings.policyDate(then.sheetId());
        Rounding now = Rounding.of(then.sheetId(), settings, sheets, claims);
        LateCharge late = new LateCharge(history::latePctOn, end, new Rounding(policy != null ? policy : end,
                now.numbered(), history.of(SettingHistory.ROUNDING)),
                LateCharge.Grace.of(history, java.util.Map.of(person.id(), grades)));
        return Dues.shown(then, grades, rates.asOf(then.sheetId(), end), history::floorOn, late);
    }

    private static BigDecimal dueNow(Claim claim, ClaimRepository claims, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets) {
        var person = people.find(claim.sheetId(), claim.personId());
        return Dues.shown(claim, person.grades(), rates, settings.floor(claim.sheetId()),
                LateCharge.of(claim.sheetId(), settings, sheets, claims, people));
    }
}

