# Add a claim to a person. A refused add (bad amount or date, unknown person, a correction that names no SETTLED claim of the person, a reference another claim on the sheet already has (without regard to case), a claim whose due-by falls in (or runs across) a period closed by hand, or one dated after the person's retirement date) writes nothing, not even an audit line.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: retired
retired:
  class: net.officefloor.hq.app.claim.RefuseRetiredNewClaim
  govern: [ transaction ]
  next: correction
correction:
  class: net.officefloor.hq.app.claim.RefuseInvalidNewCorrection
  govern: [ transaction ]
  next: ref
ref:
  class: net.officefloor.hq.app.claim.RefuseUsedNewRef
  govern: [ transaction ]
  next: closed
closed:
  class: net.officefloor.hq.app.period.RefuseClosedNewClaim
  govern: [ transaction ]
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveNewClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimAdded
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.AuditClaimRollup
  govern: [ transaction ]
  next: respond

