package net.officefloor.hq.app.period;


/** Refuse a new claim whose due-by (its date — a blank date being the sheet's entry date, else its today — plus the
 *  terms it would get) falls inside a period closed by hand (one closed automatically does not refuse it): a claim belongs to the period holding its due-by, as a pasted or
 *  template claim does. A claim whose date and due-by straddle a closed period (it would run across it: the period
 *  starts after its date and ends before its due-by) is refused too. */
public class RefuseClosedNewClaim {
    public void refuse(@Val ClaimInput input, @Val Person person, SheetRepository sheets, SettingRepository settings,
            HolidayRepository holidays, PeriodRepository periods)
            throws ClosedPeriodException {
        periods.lockSheet(person.sheetId());
        var date = input.date() != null ? input.date() : sheets.newClaimDate(person.sheetId());
        var dueBy = DueBy.of(person, date, settings, sheets, holidays);
        Period closed = periods.closedByHandFor(person.sheetId(), date, dueBy);
        if (closed != null) {
            throw new ClosedPeriodException(closed);
        }
    }
}
package net.officefloor.hq.app.claim;


/** The terms a new claim is fixed with when it is created, and the due-by they give; a claim belongs to the period
 *  holding its due-by. */
public final class DueBy {

    private DueBy() {
    }

    /** The terms (business days) a new claim of the person is fixed with: those in force on the day it is created
     *  (the sheet's today), not on its date — the person's own terms in force on that day, else the terms of their
     *  grade then in force on it (else the sheet's terms in force on it). */
    public static int terms(Person person, SettingRepository settings, SheetRepository sheets) {
        var today = sheets.today(person.sheetId());
        Integer own = person.terms().on(today);
        return own != null ? own : settings.termsFor(person.sheetId(), person.grades().on(today), today);
    }

    /** The due-by of a new claim of the person dated on the date: the terms-th business day after the date, skipping
     *  Saturdays, Sundays and the sheet's holidays as they are now. */
    public static LocalDate of(Person person, LocalDate date, SettingRepository settings, SheetRepository sheets,
            HolidayRepository holidays) {
        return holidays.dueBy(person.sheetId(), date, terms(person, settings, sheets));
    }
}

